before.content:
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
node scripts/run-stage5-real-topology.mjs
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
$dockerAvailable = $false
try {
    docker version --format '{{.Server.Version}}' 2>$null | Out-Null
    $dockerAvailable = $LASTEXITCODE -eq 0
} catch {
    $dockerAvailable = $false
}
if ($dockerAvailable) {
    docker compose -p ji-relay -f deploy/relay/compose.yaml config --quiet
    if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
    Write-Output "STAGE5_WINDOWS_COMPOSE_CONFIG_OK"
} else {
    & "$PSScriptRoot\run-stage5-ubuntu-compose.ps1"
    if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
}
Write-Output "STAGE5_GATE_OK"

after.content:
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
node scripts/run-stage5-real-topology.mjs
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
& "$PSScriptRoot\run-stage5-ubuntu-compose.ps1"
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
Write-Output "STAGE5_GATE_OK"
